// ── v37.3 : authentification Caddy (basic_auth sur /finance/) ──────────
//  Les identifiants viennent des variables d'environnement n8n, JAMAIS du
//  code : un secret écrit ici partirait dans l'export JSON du workflow.
//  Définir sur le serveur n8n : FINANCE_USER et FINANCE_PASS.
let authHeader = '';
try {
  const u = $env.FINANCE_USER, p = $env.FINANCE_PASS;
  if (u && p) authHeader = 'Basic ' + Buffer.from(u + ':' + p).toString('base64');
} catch (e) { /* $env indisponible : on part sans en-tête, comme avant */ }
const authHeaders = authHeader ? { Authorization: authHeader } : {};

// ════════════════════════════════════════════════════════
// Normalisation : unifie Telegram + Webhook en 1 payload commun
// FIX v13.3 : pour Telegram, on charge finance_data.json depuis le VPS
// (le trigger Telegram ne reçoit que du texte, pas de contexte budget).
// ════════════════════════════════════════════════════════
const item = $input.first();
const src = item.json;

let source, session_id, question, finance_data, chat_id;

if (src.message && src.message.chat) {
  // ── Telegram ──
  source = 'telegram';
  chat_id = String(src.message.chat.id);
  session_id = 'tg_' + chat_id;
  // v37.58 : liste blanche — TELEGRAM_CHAT_IDS (env n8n) ; absente : tout chat est accepté
  let _autorises = [];
  try { _autorises = String($env.TELEGRAM_CHAT_IDS || '').split(/[\s,;]+/).filter(Boolean); } catch (e) { _autorises = []; }
  if (_autorises.length && !_autorises.includes(chat_id)) return [];
  question = (src.message.text || '').trim();
  finance_data = null; // sera chargé via HTTP ci-dessous
} else if (src.body || src.question || src.session_id) {
  // ── Webhook Web ──
  const body = src.body || src;
  source = 'web';
  session_id = body.session_id || ('web_' + Date.now());
  chat_id = null;
  question = (body.question || '').trim();
  finance_data = body.finance_data || null;
} else {
  throw new Error('Payload inconnu : impossible de normaliser.');
}

if (!question) {
  throw new Error('Question vide.');
}

// ── v20.31 FIX : détection payload sanitisé ──────────────────────────────
// Le front-end v20.31 envoie un JSON épuré dans finance_data
// (contient matrice_cash_flow_calculee, pas de donneesAnnuelles).
// Les outils de mutation (budget_engine, propose_changes) ont besoin du JSON
// brut complet. On le charge depuis le VPS et on le stocke dans finance_data_raw.
const isSanitizedPayload = finance_data !== null && typeof finance_data === 'object'
  && !!finance_data.matrice_cash_flow_calculee
  && !finance_data.donneesAnnuelles;

let finance_data_raw = null;
if (!finance_data || isSanitizedPayload) {
  try {
    const fetched = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://n8n.beau.ink/finance/save_data.php',
      headers: { ...authHeaders },
      json: true,
      timeout: 10000
    });
    if (fetched && typeof fetched === 'object' && fetched.donneesAnnuelles) {
      if (isSanitizedPayload) {
        // Web v20.31 : payload sanitisé conservé dans finance_data (contexte LLM)
        // JSON brut VPS stocké dans finance_data_raw (outils de mutation seulement)
        finance_data_raw = fetched;
      } else {
        // Telegram : pas de finance_data reçu → VPS devient source principale
        finance_data = fetched;
      }
    } else {
      if (!finance_data) finance_data = null;
    }
  } catch (e) {
    if (!finance_data) finance_data = null;
  }
}

return [{
  json: {
    source,
    session_id,
    chat_id,
    question,
    finance_data_json: finance_data ? JSON.stringify(finance_data) : null,
    finance_data,
    finance_data_raw,
    finance_data_loaded_from: finance_data_raw ? 'vps_raw_for_mutations' : (finance_data ? (source === 'web' && src.body && src.body.finance_data ? 'webhook_payload' : (source === 'web' && src.finance_data ? 'webhook_payload' : 'vps_save_data_php')) : 'none')
  }
}];

