// ── v37.3 : authentification Caddy (basic_auth sur /finance/) ──────────
//  Les identifiants viennent des variables d'environnement n8n, JAMAIS du
//  code : un secret écrit ici partirait dans l'export JSON du workflow.
//  Définir sur le serveur n8n : FINANCE_USER et FINANCE_PASS.
let authHeader = '';
try {
  const u = $env.FINANCE_USER, p = $env.FINANCE_PASS;
  if (u && p) authHeader = 'Basic ' + Buffer.from(u + ':' + p).toString('base64');
} catch (e) { /* $env indisponible : on part sans en-tête, comme avant */ }
const authHeaders = authHeader ? { Authorization: authHeader } : {};

// ════════════════════════════════════════════════════════
// COMMITTER v5 — sans parametre
// Les deux seuls verrous qui protegent reellement l'ecriture sont lus a la
// source, pas declares par le modele :
//   VERROU 1 : le dernier message utilisateur vaut confirmation.
//   VERROU 2 : une simulation est effectivement en attente cote serveur.
// Le parametre `confirmation` de la v4 demandait au modele de se controler
// lui-meme ; il est supprime avec son parser.
// ════════════════════════════════════════════════════════
const PENDING_URL = 'https://n8n.beau.ink/finance/pending_commit.php';
const SAVE_URL    = 'https://n8n.beau.ink/finance/save_data.php';

let session_id = null;
try { session_id = $('Build Agent Input').first().json.session_id; } catch (e) {}
if (!session_id) { try { session_id = $('Normalize Input').first().json.session_id; } catch (e) {} }
if (!session_id) return JSON.stringify({ error: 'session_id introuvable dans le contexte' });

// ── VERROU 1 : la confirmation vient de l'utilisateur, pas du modele ──
let lastUserMsg = '';
try { lastUserMsg = String($('Normalize Input').first().json.question || '').toUpperCase(); } catch (e) {}
if (!/\bOUI\b|\bOK\b|\bVALIDE\b|\bGO\b/.test(lastUserMsg)) {
  return JSON.stringify({ error: 'REFUS : le dernier message utilisateur ne contient pas OUI/OK/VALIDE. Demande confirmation explicite.' });
}

// ── VERROU 2 : une simulation attend bien d'etre appliquee ──
let pending;
try {
  pending = await this.helpers.httpRequest({
    method: 'GET',
    url: PENDING_URL + '?session_id=' + encodeURIComponent(session_id),
    headers: { ...authHeaders },
    json: true,
    timeout: 10000
  });
} catch (e) {
  return JSON.stringify({
    error: 'Aucune simulation en attente. Demande a l\'utilisateur de reformuler sa modification (ex : "baisse le loyer a 4500"), je referai la simulation puis tu pourras valider par OUI.',
    detail: e.message,
    session_id
  });
}
if (!pending || !pending.finance_data || !pending.finance_data.donneesAnnuelles) {
  return JSON.stringify({
    error: 'Pending recupere mais finance_data invalide. Demande a l\'utilisateur de relancer la simulation.',
    session_id,
    pending_keys: pending ? Object.keys(pending) : null
  });
}

const operations = pending.operations || [];

// ── Commit ──
let saveResp;
try {
  saveResp = await this.helpers.httpRequest({
    method: 'POST',
    url: SAVE_URL,
    body: pending.finance_data,
    json: true,
    headers: { 'Content-Type': 'application/json', ...authHeaders },
    timeout: 15000
  });
} catch (e) {
  return JSON.stringify({ error: 'Echec ecriture save_data.php', detail: e.message, session_id, pending_preserved: true });
}

// ── Cleanup best effort : le pending expire seul apres 30 min ──
let pendingDeleted = false;
try {
  const delResp = await this.helpers.httpRequest({
    method: 'DELETE',
    url: PENDING_URL + '?session_id=' + encodeURIComponent(session_id),
    headers: { ...authHeaders },
    json: true,
    timeout: 5000
  });
  pendingDeleted = !!(delResp && delResp.status === 'ok');
} catch (e) {}

return JSON.stringify({
  status: 'ok',
  committed: true,
  session_id,
  annee: pending.annee,
  operations_count: operations.length,
  operations,
  pending_deleted: pendingDeleted,
  server_response: saveResp
});

// ════════════════════════════════════════════════════════
// FORMAT FOR TELEGRAM v37.58
//   Telegram (parse_mode HTML) REFUSE tout le message — 400, aucune réponse —
//   si le texte contient un « < » ou un « & » nu, une balise non fermée, ou
//   s'il dépasse 4 096 caractères. Ici :
//     • seules <b> <i> <u> <s> <code> <pre> <a href> survivent, équilibrées ;
//     • tout le reste du texte est ré-échappé (&lt; &gt; &amp;) ;
//     • tableaux : « cellule · cellule », une ligne par rangée ;
//     • une réponse longue part en plusieurs messages (≤ 3 900 car.).
// ════════════════════════════════════════════════════════
const LIMITE = 3900;
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const echapper = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const decoder = (s) => String(s)
  .replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
  .replace(/&amp;/g, '&');

let html = '';
let isError = false;
let errorDetail = '';
try {
  const agentOut = $('AI Agent').first().json;
  if (agentOut.error) {
    isError = true;
    errorDetail = typeof agentOut.error === 'string' ? agentOut.error : (agentOut.error.message || JSON.stringify(agentOut.error));
  } else {
    html = agentOut.output || agentOut.text || agentOut.response || '';
    if (!html) { isError = true; errorDetail = 'Aucune réponse générée (output vide après continueOnFail).'; }
  }
} catch (e) {
  isError = true;
  errorDetail = e.message || 'Exception lors de la lecture de la sortie agent.';
}
if (isError) {
  return [{ json: { chat_id: chatId, telegram_text: '⚠️ <b>Alerte Système (Super-Agent CFO)</b>\n'
    + 'Une exception a empêché l\'exécution correcte de la commande.\n'
    + '<b>Détail technique :</b> <code>' + echapper(String(errorDetail).slice(0, 1500)) + '</code>' } }];
}

// 1. Mise en page : blocs → sauts de ligne, tableaux → « a · b », listes → puces
const plat = String(html)
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(?:td|th)>\s*(?=<(?:td|th)\b)/gi, ' · ')
  .replace(/<\/tr>/gi, '\n')
  .replace(/<\/p>\s*<p[^>]*>/gi, '\n\n')
  .replace(/<\/li>/gi, '\n')
  .replace(/<li[^>]*>/gi, '• ')
  .replace(/<hr\s*\/?>/gi, '\n———\n')
  .replace(/<\/?(?:p|div|ul|ol|table|thead|tbody|h[1-6])\b[^>]*>/gi, '\n')
  .replace(/<(\/?)strong\b[^>]*>/gi, '<$1b>').replace(/<(\/?)em\b[^>]*>/gi, '<$1i>');

// 2. Jetons : balise permise, ou texte (toute autre balise disparaît)
const jetons = [];
const re = /<(\/?)([a-z][a-z0-9]*)\b([^>]*)>/gi;
let i = 0, m;
const texte = (s) => { if (s) jetons.push({ t: echapper(decoder(s)) }); };
while ((m = re.exec(plat))) {
  texte(plat.slice(i, m.index)); i = re.lastIndex;
  const nom = m[2].toLowerCase(), ferme = m[1] === '/';
  if (!['b', 'i', 'u', 's', 'code', 'pre', 'a'].includes(nom)) continue;
  if (nom === 'a' && !ferme) {
    const h = /href\s*=\s*["']([^"']+)["']/i.exec(m[3]);
    if (!h || !/^https?:\/\//i.test(decoder(h[1]))) { jetons.push({ ouvre: 'a', vide: true }); continue; }
    jetons.push({ ouvre: 'a', balise: '<a href="' + echapper(decoder(h[1])).replace(/"/g, '&quot;') + '">' });
  } else if (ferme) jetons.push({ ferme: nom });
  else jetons.push({ ouvre: nom, balise: '<' + nom + '>' });
}
texte(plat.slice(i));

// 3. Morceaux ≤ LIMITE, balises équilibrées dans chacun
const morceaux = [];
let cour = '', pile = [];
const fermer = () => pile.slice().reverse().map(p => p.vide ? '' : '</' + p.ouvre + '>').join('');
const rouvrir = () => pile.map(p => p.vide ? '' : p.balise).join('');
const couper = () => { const s = (cour + fermer()).replace(/\n{3,}/g, '\n\n').trim(); if (s.replace(/<[^>]+>/g, '').trim()) morceaux.push(s); cour = rouvrir(); };
for (const j of jetons) {
  if (j.ouvre) { pile.push(j); cour += j.vide ? '' : j.balise; continue; }
  if (j.ferme) {
    const k = pile.map(p => p.ouvre).lastIndexOf(j.ferme);
    if (k < 0) continue;                                   // fermeture orpheline : ignorée
    const dessus = pile.splice(k);
    cour += dessus.slice().reverse().map(p => p.vide ? '' : '</' + p.ouvre + '>').join('');
    cour += dessus.slice(1).map(p => p.vide ? '' : p.balise).join('');
    pile.push(...dessus.slice(1));
    continue;
  }
  let reste = j.t;
  while (cour.length + reste.length + fermer().length > LIMITE) {
    const place = Math.max(0, LIMITE - cour.length - fermer().length);
    let cut = Math.max(reste.lastIndexOf('\n', place), reste.lastIndexOf(' ', place));
    if (cut <= 0) cut = place;
    while (cut > 0 && /&[a-z#0-9]*$/i.test(reste.slice(0, cut))) cut--;   // ne pas couper une entité
    if (cut <= 0 && cour.replace(/<[^>]+>/g, '').trim()) { couper(); continue; }
    if (cut <= 0) cut = Math.min(reste.length, LIMITE);
    cour += reste.slice(0, cut); reste = reste.slice(cut).replace(/^[ \n]+/, '');
    couper();
  }
  cour += reste;
}
couper();
if (!morceaux.length) morceaux.push('(réponse vide)');
return morceaux.map((t, n) => ({ json: { chat_id: chatId, telegram_text: morceaux.length > 1 ? t + '\n<i>(' + (n + 1) + '/' + morceaux.length + ')</i>' : t } }));

// ════════════════════════════════════════════════════════
// MEMORY WRITER v2 — schema d'entree declare cote n8n
// Le modele remplit {texte, categorie}. Plus de regex : il REFORMULE,
// ce qu'un pattern ne saura jamais faire.
// ════════════════════════════════════════════════════════
const VALID_CATS = ['preference', 'regle', 'contexte', 'general'];

// Normalisation : `query` arrive en objet (schema lu) ou en chaine JSON.
let input = {};
try {
  input = (typeof query === 'string') ? JSON.parse(query) : (query || {});
} catch (e) { input = {}; }

const texte = String(input.texte || '').trim();
let categorie = String(input.categorie || 'general').trim().toLowerCase();
if (!VALID_CATS.includes(categorie)) categorie = 'general';

if (texte.length < 5) {
  return JSON.stringify({
    error: 'TEXTE_MANQUANT',
    raison: 'Le parametre "texte" est vide ou trop court.',
    attendu: { texte: 'phrase autonome a memoriser', categorie: VALID_CATS.join('|') }
  });
}

let session_id = null;
try { session_id = $('Build Agent Input').first().json.session_id; } catch (e) {}
if (!session_id) { try { session_id = $('Normalize Input').first().json.session_id; } catch (e) {} }

const requestBody = { texte, categorie, session_id: session_id || 'unknown' };

try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://n8n.beau.ink/webhook/finance-memory-ingest',
    body: requestBody,
    json: true,
    timeout: 20000
  });
  if (resp && resp.status === 'ok') {
    return JSON.stringify({ status: 'ok', memorise: true, texte, categorie });
  }
  return JSON.stringify({ error: 'INGESTION_REPONSE_KO', response_recue: resp, request_envoyee: requestBody });
} catch (e) {
  // Le diagnostic est conserve : il a une vraie valeur d'exploitation.
  const code = (e && (e.statusCode || e.code)) || null;
  let cause = null;
  if (code === 404) cause = 'Sous-workflow CFO Memory Ingest non ACTIVE';
  else if (code === 500) cause = 'Sous-workflow leve une exception';
  else if (/ECONNREFUSED|ENOTFOUND|timeout/i.test((e && e.message) || '')) cause = 'Reseau / DNS / timeout';
  return JSON.stringify({
    error: 'WEBHOOK_ECHEC',
    e_message: (e && e.message) || null,
    e_statusCode: code,
    request_envoyee: requestBody,
    cause_probable: cause
  });
}

