// ── v37.3 : authentification Caddy (basic_auth sur /finance/) ──────────
//  Les identifiants viennent des variables d'environnement n8n, JAMAIS du
//  code : un secret écrit ici partirait dans l'export JSON du workflow.
//  Définir sur le serveur n8n : FINANCE_USER et FINANCE_PASS.
let authHeader = '';
try {
  const u = $env.FINANCE_USER, p = $env.FINANCE_PASS;
  if (u && p) authHeader = 'Basic ' + Buffer.from(u + ':' + p).toString('base64');
} catch (e) { /* $env indisponible : on part sans en-tête, comme avant */ }
const authHeaders = authHeader ? { Authorization: authHeader } : {};

// ════════════════════════════════════════════════════════
// INTENT COMPILER v2 — routeur HTTP
// Tout le metier (catalogue, Levenshtein, applyOp, snapshots, deltas) vit
// desormais sur le VPS, dans cfo_intent_engine.php appele par
// pending_commit.php. Ce noeud ne fait plus que trois choses :
//   1. recuperer les calls produits par le modele (schema declare ci-dessus)
//   2. y joindre le session_id et le SSOT du net mensuel
//   3. relayer la reponse du serveur telle quelle
// ════════════════════════════════════════════════════════
const ENDPOINT = 'https://n8n.beau.ink/finance/pending_commit.php';

// Normalisation : `query` arrive en objet (schema lu) ou en chaine JSON.
let input = {};
try { input = (typeof query === 'string') ? JSON.parse(query) : (query || {}); } catch (e) { input = {}; }

const calls = Array.isArray(input.calls) ? input.calls : (Array.isArray(input) ? input : null);
if (!calls || !calls.length) {
  return JSON.stringify({
    error: 'Parametre "calls" manquant ou vide.',
    format_attendu: { calls: [{ function: '<nom du catalogue>', args: {} }] }
  });
}

let normalized;
try { normalized = $('Build Agent Input').first().json; }
catch (e) {
  try { normalized = $('Normalize Input').first().json; }
  catch (e2) { return JSON.stringify({ error: 'Contexte introuvable (Build Agent Input / Normalize Input)' }); }
}
const session_id = normalized.session_id;
if (!session_id) return JSON.stringify({ error: 'session_id introuvable dans le contexte' });

// SSOT du net mensuel isole du Compte Courant, exporte par l'application web.
// Le backend sait le recalculer, mais quand l'appli l'a deja fourni c'est LUI
// qui fait foi : il reflete ce que l'utilisateur voit a l'ecran.
const ssot = (normalized.finance_data && normalized.finance_data.surplus_mensuel_net_courant) || null;

// v35.5 : l'exercice REELLEMENT expose au modele part avec les calls. Sans lui,
//   un appel sans `year` retombait cote serveur sur date('Y') -- l'horloge du
//   VPS -- donc sur 2026 quoi qu'il arrive. Un `year` explicite dans un call
//   reste prioritaire : ce parametre n'est qu'un defaut, jamais un forcage.
const annee_contexte = Number(normalized.exercice_expose) || null;

let resp;
try {
  resp = await this.helpers.httpRequest({
    method: 'POST',
    url: ENDPOINT,
    body: { session_id, calls, surplus_mensuel_net_courant: ssot, annee_contexte },
    headers: { ...authHeaders },
    json: true,
    timeout: 25000
  });
} catch (e) {
  // v35.1 : NE JAMAIS inventer la cause. La v1 renvoyait une cause_probable
  // codee en dur ("pending_commit.php absent...") meme quand le serveur avait
  // repondu avec un diagnostic precis — ce qui a envoye tout un debug sur une
  // fausse piste. On distingue desormais deux situations franchement.
  const status = (e && (e.statusCode || e.status || (e.response && e.response.statusCode))) || null;
  let body = (e && e.response && e.response.body) || (e && e.error) || null;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (_) { /* corps non-JSON : relaye brut */ } }

  // Hors catalogue : arret franc, le modele ne doit pas enchainer.
  if (body && body.error === 'ERROR_OUT_OF_CATALOG') {
    // v37.5 : on RETOURNE au lieu de jeter — une exception ici tue l'agent
    //   entier et l'utilisateur ne recoit aucune explication.
    return JSON.stringify({
      error: 'ERROR_OUT_OF_CATALOG',
      message: body.message || "L'action demandee n'existe pas dans le catalogue.",
      catalogue: body.catalogue || null,
      consigne: "N'invente PAS de fonction de remplacement. Dis a l'utilisateur que cette action n'existe pas encore et propose de la faire developper."
    });
  }

  // CAS 1 — le serveur A repondu : on relaie SON diagnostic, mot pour mot.
  //   pending_commit.php renvoie desormais error/class/file/line (COMPILE_EXCEPTION,
  //   FATAL_PHP, PENDING_DIR_NOT_WRITABLE...) : tout est deja dans body.
  if (body) {
    return JSON.stringify({ error: 'BACKEND_ERREUR', http_status: status, reponse_serveur: body });
  }

  // CAS 2 — aucune reponse : la, oui, le backend est vraiment injoignable.
  return JSON.stringify({
    error: 'BACKEND_INJOIGNABLE',
    detail: (e && e.message) || null,
    http_status: status,
    endpoint: ENDPOINT,
    cause_probable: "Aucune reponse HTTP recue (DNS, reseau, ou service arrete). Si le serveur avait repondu, son message figurerait ici."
  });
}

if (resp && resp.error === 'ERROR_OUT_OF_CATALOG') {
  return JSON.stringify({
    error: 'ERROR_OUT_OF_CATALOG',
    message: resp.message || "L'action demandee n'existe pas dans le catalogue.",
    catalogue: resp.catalogue || null,
    consigne: "N'invente PAS de fonction de remplacement. Dis a l'utilisateur que cette action n'existe pas encore et propose de la faire developper."
  });
}
return JSON.stringify(resp);

